"""Isolated offline browser checks for the three authorized v3.1-v3.3 specs."""
import json,time,base64
def run(c,root,name):
 out=root/'tests/update33-evidence';out.mkdir(exist_ok=True)
 c.call('Emulation.setDeviceMetricsOverride',{'width':1366,'height':900,'deviceScaleFactor':1,'mobile':False})
 c.navigate(root/'index.html')
 for _ in range(250):
  if c.evaluate('!!window.AL?.game&&!!AL.Update31UI'):break
  time.sleep(.04)
 else:
  print(json.dumps([e for e in c.events if e.get('method')=='Runtime.exceptionThrown'],indent=2));return 1
 c.evaluate("AL.Startup.finish();AL.game.settings.speed=0;AL.UI.close();AL.Store.close();AL.Shell.close();AL.game.update29.tutorial.status='skipped';AL.Update29UI.updateTutorial()")
 result=c.evaluate((root/'tests/update33_checks.js').read_text(encoding='utf-8'))
 (out/f'{name}-logic-results.json').write_text(json.dumps(result,indent=2),encoding='utf-8')
 print(json.dumps({'passed':result['passed'],'failed':result['failed'],'failures':[r for r in result['checks'] if not r['pass']]},indent=2),flush=True)
 if result['failed']:return 1
 coverage=c.evaluate("AL.Research.catalog().map(r=>({id:r.d.id,canonicalSpeciesId:r.id,name:r.d.name,scientificName:r.d.scientificName||null,eligible:r.eligible,status:'Research Data Incomplete',sourceBackedAnnotations:!!r.data?.reviewed,sourceIds:r.data?.sources||[]}))")
 (root/'planning/v3.1-v3.3/research-coverage.json').write_text(json.dumps({'accessDate':'2026-10-14','indexed':len(coverage),'researchableBiologicalSpecies':len(set(r['canonicalSpeciesId'] for r in coverage if r['eligible'])),'complete':0,'incomplete':sum(r['eligible'] for r in coverage),'entries':coverage},indent=2),encoding='utf-8')
 ui=[]
 def check(label,expression):
  try:ui.append({'name':label,'pass':bool(c.evaluate(expression))})
  except Exception as exc:ui.append({'name':label,'pass':False,'error':str(exc)})
 def shot(label):
  data=c.call('Page.captureScreenshot',{'format':'png','captureBeyondViewport':False})['data']
  (out/f'{name}-{label}.png').write_bytes(base64.b64decode(data))
 c.evaluate("AL.game=v33Fixture();AL.UI.render();window.v33Destination=AL.game.selectedTank;document.getElementById('finance-open').click()")
 check('AC icon/amount is one native accessible button and opens the financial modal',"document.getElementById('finance-open').tagName==='BUTTON'&&document.getElementById('finance-dialog').open&&document.getElementById('finance-dialog').textContent.includes('Financial Overview')")
 check('Dashboard shows balance, opening, income, expenses, net and closing separately',"['Current Balance','Period Opening','Income','Expenses','Net Change','Period Closing'].every(t=>document.getElementById('finance-summary').textContent.includes(t))")
 shot('financial-opening')
 c.evaluate("document.querySelector('[data-v31=financeClose]').click()")
 check('Financial modal X closes cleanly',"!document.getElementById('finance-dialog').open")
 c.evaluate("document.getElementById('finance-open').focus()")
 c.call('Input.dispatchKeyEvent',{'type':'keyDown','key':'Enter','code':'Enter','windowsVirtualKeyCode':13})
 c.call('Input.dispatchKeyEvent',{'type':'keyUp','key':'Enter','code':'Enter','windowsVirtualKeyCode':13})
 check('Keyboard Enter activates the AC control',"document.getElementById('finance-dialog').open")
 c.call('Input.dispatchKeyEvent',{'type':'keyDown','key':'Escape','code':'Escape','windowsVirtualKeyCode':27})
 c.call('Input.dispatchKeyEvent',{'type':'keyUp','key':'Escape','code':'Escape','windowsVirtualKeyCode':27})
 check('Escape dismisses the financial modal',"!document.getElementById('finance-dialog').open")
 c.evaluate("document.getElementById('finance-open').click()")
 c.call('Input.dispatchMouseEvent',{'type':'mousePressed','x':2,'y':2,'button':'left','clickCount':1})
 c.call('Input.dispatchMouseEvent',{'type':'mouseReleased','x':2,'y':2,'button':'left','clickCount':1})
 check('Backdrop click dismisses the financial modal',"!document.getElementById('finance-dialog').open")
 c.evaluate("AL.game=AL.Core.act(AL.game,'buyFood',{type:'pellets'});AL.game=AL.Core.act(AL.game,'buyResearch',{species:'gramma'});document.getElementById('finance-open').click()")
 check('Real purchase and research receipts appear with resulting balances and details',"document.getElementById('finance-history').querySelectorAll('details').length===2&&document.getElementById('finance-history').textContent.includes('Species Research')&&document.getElementById('finance-history').textContent.includes('Resulting balance')")
 c.evaluate("document.getElementById('finance-direction').value='income';document.getElementById('finance-direction').dispatchEvent(new Event('change',{bubbles:true}))")
 check('Income filter excludes expense-only receipts without changing wallet',"document.querySelectorAll('#finance-history details').length===0")
 c.evaluate("document.getElementById('finance-direction').value='all';document.getElementById('finance-direction').dispatchEvent(new Event('change',{bubbles:true}));document.getElementById('finance-category').value='research';document.getElementById('finance-category').dispatchEvent(new Event('change',{bubbles:true}))")
 check('Category filter selects only actual research receipts',"document.querySelectorAll('#finance-history details').length===1&&document.getElementById('finance-history').textContent.includes('gramma')")
 c.evaluate("document.getElementById('finance-period').value='7';document.getElementById('finance-period').dispatchEvent(new Event('change',{bubbles:true}))")
 check('Timeframe change preserves honest reconciliation',"document.getElementById('finance-summary').textContent.includes('closing')&&AL.Finance.summary(AL.game,7).closing===AL.game.credits")
 started=c.evaluate('AL.game.time');time.sleep(5.3)
 check('Aquarium simulation continues while financial dashboard is open',f'AL.game.time>{started}')
 shot('financial-transactions')
 c.evaluate("document.querySelector('[data-v31=financeClose]').click();AL.Shell.open('equipment','fragging')")
 check('Coral Fragging category lives in the existing Equipment window',"AL.Shell.active==='equipment'&&document.getElementById('primary-content').textContent.includes('Coral Fragging Kit')&&document.getElementById('primary-content').textContent.includes('Precision Coral Cutters')&&document.getElementById('primary-content').textContent.includes('Coral Frag Saw')")
 c.evaluate("document.querySelector('[data-v31=fragRack]').click()")
 check('Frag Rack link opens the actual existing 100-AC equipment product',"AL.Store.category==='equipment'&&AL.Store.products().some(p=>p.kind==='rack'&&p.price===100)")
 c.evaluate("AL.Store.close()")
 c.evaluate("AL.Shell.close();AL.game=v33Fixture();window.parent33=v33Coral(AL.game);AL.UI.render();AL.UI.inspectFlora(parent33.id)")
 check('Mature coral inspector shows locked Frag Coral and explicit missing-tool reason',"document.getElementById('dialog-body').textContent.includes('Frag Coral')&&document.querySelector('[data-v31=frag]').disabled&&document.getElementById('dialog-body').textContent.includes('Precision Coral Cutters')")
 c.evaluate("AL.UI.close();AL.game=AL.Core.act(AL.game,'buyFragTool',{tool:'cutters'});AL.game=AL.Core.act(AL.game,'buyFragSupplies',{supply:'plugs'});AL.game=AL.Core.act(AL.game,'buyFragSupplies',{supply:'mounting'});AL.UI.inspectFlora(parent33.id);document.querySelector('[data-v31=frag]').click()")
 check('Fragging modal previews real parent, method, mount, risk, tissue and estimated value before committing',"['Health','age','size','Required Precision','eligible fragment','Parent loses','Estimated fragment asset value'].every(t=>document.getElementById('dialog-body').textContent.includes(t))&&AL.game.tanks[0].flora.length===1&&document.getElementById('frag-confirm')!==null")
 shot('frag-confirmation')
 c.evaluate("document.querySelector('[data-v31=cancelFrag]').click()")
 check('Cancel does not cut or consume resources',"AL.game.tanks[0].flora.length===1&&AL.game.inventory['frag-plugs']===10")
 c.evaluate("AL.Update31UI.fragDialog(parent33.id);document.getElementById('frag-confirm').requestSubmit()")
 check('Actual confirmation creates one mounted clone and retains reusable tool',"AL.game.tanks[0].flora.length===2&&AL.game.tanks[0].flora[1].parentId===parent33.id&&AL.game.inventory['frag-plugs']===9&&AL.game.inventory['frag-cutters']===1&&!document.getElementById('dialog').open")
 c.evaluate("AL.Shell.open('journal','breeding')")
 check('Field Journal records parent/child clone lineage and trading education',"document.getElementById('primary-content').textContent.includes('Player-fragged clone lineage')&&document.getElementById('primary-content').textContent.includes(parent33.id)&&document.getElementById('primary-content').textContent.includes('60%')")
 c.evaluate("AL.Shell.close();AL.Store.open('research','saltwater')")
 check('Research lives under Saltwater Store without a seventh sidebar window',"document.getElementById('store-products').textContent.includes('Marine Research Center')&&document.querySelectorAll('#navigation [data-page]').length===6")
 check('Every marine record is searchable and indexed; incomplete data is clear',"document.querySelectorAll('#research-results .research-row').length===AL.Research.catalog().length&&document.getElementById('store-products').textContent.includes('Research Data Incomplete')")
 c.evaluate("document.getElementById('research-search').value='Gramma loreto';document.getElementById('research-search').dispatchEvent(new Event('input',{bubbles:true}))")
 check('Scientific-name search finds the actual species',"document.querySelectorAll('#research-results .research-row').length===1&&document.getElementById('research-results').textContent.includes('Royal gramma')")
 c.evaluate("document.querySelector('#research-results [data-v31=researchReport]').click()")
 check('Free research preview explains five-credit permanent unlock and data limits',"document.getElementById('dialog-body').textContent.includes('5 AC')&&document.getElementById('dialog-body').textContent.includes('Research Data Incomplete')")
 money=c.evaluate('AL.game.credits')
 c.evaluate("document.querySelector('[data-v31=researchBuy]').click()")
 check('Actual research purchase charges exactly five AC once and shows all ten report sections',f"AL.game.credits==={money}-5&&['A. Species Identification','B. Natural Habitat','C. Aquarium Care','D. Diet and Feeding','E. Temperament','F. Growth and Lifespan','G. Breeding','H. Medical Information','I. Interesting Facts','J. Game Information'].every(t=>document.getElementById('dialog-body').textContent.includes(t))")
 check('Report shows source attribution, honest unknowns and game/science distinction',"['Smithsonian','unverified','NOT independently verified','NOT conservation status'].every(t=>document.getElementById('dialog-body').textContent.includes(t))")
 shot('species-research')
 started=c.evaluate('AL.game.time');time.sleep(5.3)
 check('Aquarium simulation continues during research report reading',f'AL.game.time>{started}')
 c.evaluate("document.querySelector('[data-v31=medicalGuide]').click()")
 check('Research medical section opens the existing Disease & Treatment Guide',"AL.Shell.active==='journal'&&AL.Shell.subtab==='disease'")
 c.evaluate("AL.Shell.close();AL.Shell.open('journal','encyclopedia');document.querySelector('[data-action=journalSpecies][data-args*=gramma]').click()")
 check('Species Encyclopedia uses the same permanent research unlock and report',"document.getElementById('dialog-body').textContent.includes('Gramma loreto')&&document.getElementById('dialog-body').textContent.includes('A. Species Identification')&&!document.querySelector('[data-v31=researchBuy]')")
 c.evaluate("AL.UI.close();AL.Shell.close();AL.Store.open('wanted','black')")
 check('Deep Market has Wanted Livestock requests separate from sale stock',"document.getElementById('store-products').textContent.includes('Wanted Livestock')&&document.getElementById('store-products').textContent.includes('four daily sale-stock slots')&&AL.game.update31.market.stock.length===4")
 shot('wanted-board')
 c.evaluate("AL.Store.open('fish','black');AL.Store.close();AL.Store.open('fish','saltwater')")
 check('Store reopen/tab changes preserve selected aquarium and eight ordinary fish slots',"AL.game.selectedTank===v33Destination&&AL.Store.products().length===8")
 c.evaluate("document.querySelector('[data-store-mode=sell]').click()")
 check('Saltwater Sell lists individual corals and actual offers without old flat cutting duplication',"document.getElementById('store-products').textContent.includes('Fresh fragment is not yet established')&&!document.getElementById('store-products').textContent.includes('Sell cutting')")
 for width,height in [(390,844),(768,1024),(1366,900),(1920,1080)]:
  c.evaluate('AL.Store.close();AL.UI.close();AL.Update31UI.openFinance()')
  c.call('Emulation.setDeviceMetricsOverride',{'width':width,'height':height,'deviceScaleFactor':1,'mobile':False})
  time.sleep(.1)
  check(f'Financial dashboard fits viewport {width}',"document.documentElement.scrollWidth<=innerWidth+2&&document.getElementById('finance-dialog').getBoundingClientRect().right<=innerWidth+2")
  if width in [390,1366]:shot('financial-'+str(width))
  c.evaluate("document.querySelector('[data-v31=financeClose]').click()")
 c.evaluate("AL.Store.close();AL.UI.close();AL.UI.save();window.savedResearch33=JSON.stringify(AL.game.research);window.savedFinance33=AL.game.finance.next;AL.game.settings.speed=0;AL.UI.save()")
 account=c.evaluate('AL.game.accountId');unlocks=c.evaluate('JSON.stringify(AL.game.research.unlocks)')
 c.navigate(root/'index.html')
 for _ in range(250):
  if c.evaluate('!!window.AL?.game&&!!AL.Update31UI'):break
  time.sleep(.04)
 check('Actual reload preserves account identity, financial history and research unlocks',f'AL.game.accountId==={json.dumps(account)}&&JSON.stringify(AL.game.research.unlocks)==={json.dumps(unlocks)}&&AL.game.finance.rows.some(r=>r.category==="research")')
 errors=[e for e in c.events if e.get('method')=='Runtime.exceptionThrown']
 ui.append({'name':'No uncaught JavaScript errors in the new flows','pass':not errors,'errors':errors})
 network=[e['params']['request']['url'] for e in c.events if e.get('method')=='Network.requestWillBeSent' and e['params']['request']['url'].startswith(('http:','https:'))]
 ui.append({'name':'All gameplay and research data run offline without HTTP requests','pass':not network,'requests':network})
 report={'passed':result['passed']+sum(r['pass'] for r in ui),'failed':result['failed']+sum(not r['pass'] for r in ui),'logic':result,'ui':ui}
 (out/f'{name}-results.json').write_text(json.dumps(report,indent=2),encoding='utf-8')
 print(json.dumps({'passed':report['passed'],'failed':report['failed'],'failures':[r for r in ui if not r['pass']]},indent=2),flush=True)
 return int(bool(report['failed']))
